import type { EventEnvelope, MarketEvent } from "@market/core";
import type { Player } from "./player";

// Live mode: subscribes to the SpacetimeDB `run_event` table and pushes rows
// into the Player. The typed client is generated by
//   spacetime generate --lang typescript --out-dir apps/portal/src/stdb/module_bindings
// and loaded lazily, so the portal builds and replays fine without it.

const bindings = import.meta.glob("../stdb/module_bindings/index.ts");

export interface LiveRun {
  runId: string;
  label: string;
  status: string;
  startedAt: number;
}

export interface LiveHandle {
  runs: () => LiveRun[];
  watch: (runId: string) => void;
  onRuns: (cb: () => void) => void;
  disconnect: () => void;
}

export function liveAvailable(): boolean {
  return Object.keys(bindings).length > 0;
}

export async function connectLive(player: Player): Promise<LiveHandle> {
  const loader = Object.values(bindings)[0];
  if (!loader) throw new Error("SpacetimeDB bindings not generated. Run `spacetime generate` (see spacetime/README.md).");
  // Generated code; its exact table accessor names come from the module.
  const mod = (await loader()) as { DbConnection: any };
  const uri = import.meta.env.VITE_SPACETIMEDB_URI ?? "wss://maincloud.spacetimedb.com";
  const db = import.meta.env.VITE_SPACETIMEDB_DB_NAME ?? "market-sim";

  let runsCb: () => void = () => {};
  let watching: string | null = null;
  let sub: { unsubscribe: () => void } | null = null;

  const conn = await new Promise<any>((resolve, reject) => {
    mod.DbConnection.builder()
      .withUri(uri)
      .withDatabaseName(db)
      .onConnect((c: any) => resolve(c))
      .onConnectError((_ctx: unknown, err: Error) => reject(err))
      .build();
  });

  const table = (name: string) => conn.db[name] ?? conn.db[name.replace(/_(\w)/g, (_: string, ch: string) => ch.toUpperCase())];
  const runTable = table("run");
  const eventTable = table("run_event");

  conn.subscriptionBuilder().onApplied(() => runsCb()).subscribe(["SELECT * FROM run"]);
  runTable.onInsert(() => runsCb());
  runTable.onUpdate?.(() => runsCb());

  const toEnv = (row: any): EventEnvelope => ({
    runId: row.runId ?? row.run_id,
    seq: Number(row.seq),
    ts: Number(row.ts),
    event: JSON.parse(row.payload) as MarketEvent,
  });

  eventTable.onInsert((_ctx: unknown, row: any) => {
    const env = toEnv(row);
    if (env.runId === watching) player.push(env);
  });

  return {
    runs: () =>
      [...runTable.iter()]
        .map((r: any) => ({ runId: r.runId ?? r.run_id, label: r.label, status: r.status, startedAt: Number(r.startedAt ?? r.started_at) }))
        .sort((a: LiveRun, b: LiveRun) => b.startedAt - a.startedAt),
    watch: (runId: string) => {
      sub?.unsubscribe();
      watching = runId;
      player.startLive();
      sub = conn
        .subscriptionBuilder()
        .onApplied(() => {
          // Initial rows arrive through onInsert as the subscription applies.
        })
        .subscribe([`SELECT * FROM run_event WHERE run_id = '${runId.replace(/'/g, "''")}'`]);
    },
    onRuns: (cb) => {
      runsCb = cb;
      cb();
    },
    disconnect: () => conn.disconnect(),
  };
}
